SELECT 'batch_015_4854213f_flac_05' AS batch_id,(SELECT COUNT(*) FROM song_masters WHERE id IN ('sm-826bbf27707049f088b67dcfe4b2909d','sm-ff03e1e966b7481cb1db2620812de72e','sm-upload-1dad7e8b-f48','sm-upload-225801dc-e26','sm-upload-958b08f3-738') AND album_id='al-0e047abb5cbbdac294a9db7f4854213f') AS candidate_masters_in_target,(SELECT COUNT(*) FROM song_masters WHERE id IN ('sm-826bbf27707049f088b67dcfe4b2909d','sm-ff03e1e966b7481cb1db2620812de72e','sm-upload-1dad7e8b-f48','sm-upload-225801dc-e26','sm-upload-958b08f3-738') AND album_id='pending-uploads') AS candidate_masters_still_pending,(SELECT COUNT(*) FROM albums WHERE id='al-0e047abb5cbbdac294a9db7f4854213f' AND name='四季有时') AS target_album_rows,(SELECT song_count FROM albums WHERE id='al-0e047abb5cbbdac294a9db7f4854213f') AS stored_song_count,(SELECT COALESCE(SUM(si.size),0) FROM song_instances si JOIN song_masters sm ON sm.id=si.master_id WHERE sm.album_id='al-0e047abb5cbbdac294a9db7f4854213f') AS calculated_size;
